// Chinese lunar and solar term calculation for the native popover.
// Exports: LunarCalendar, LunarDate
// Deps: Foundation Calendar and LocalDate
//
// Solar term days come from a packed table generated by
// packages/core-calendar/tools/generate-solar-term-table.ts (astronomy-engine
// apparent solar longitude read in UTC+8, cross-validated against the
// 寿星天文历 ephemeris). It must stay byte-identical to the TypeScript copy in
// packages/core-calendar/src/solar-term-table.ts.

import Foundation

struct LunarDate {
    let yearName: String
    let monthName: String
    let dayName: String
    let solarTerm: String?
}

