    func lunarDate(for date: LocalDate) -> LunarDate? {
        // The table starts at lunar new year 1949 (1949-01-29); earlier days
        // of 1949 belong to lunar year 1948, which it cannot represent.
        guard date.year >= 1949 && date.year <= 2100 else {
            return nil
        }
        guard date.year > 1949 || date.month > 1 || date.day >= 29 else {
            return nil
        }
        guard let parts = lunarParts(for: date) else {
            return nil
        }
        return LunarDate(
            yearName: yearName(parts.year),
            monthName: monthName(parts.month, isLeap: parts.isLeapMonth),
            dayName: dayName(parts.day),
            solarTerm: solarTerm(for: date)
        )
    }

    private func lunarParts(for date: LocalDate) -> (year: Int, month: Int, isLeapMonth: Bool, day: Int)? {
        var daySpan = daysSinceBase(date) + 1
        var lunarYear = 0
        for index in 0..<yearData.count {
            daySpan -= lunarYearDays(yearData[index])
            if daySpan <= 0 {
                lunarYear = 1949 + index
                daySpan += lunarYearDays(yearData[index])
                break
            }
        }
        guard lunarYear > 0 else {
            return nil
        }
        let data = yearData[lunarYear - 1949]
        let months = lunarYearMonths(data)
        for index in 0..<months.count {
            daySpan -= months[index]
            if daySpan <= 0 {
                let month = normalizedMonth(index, leapMonth(data))
                return (lunarYear, month.number, month.isLeap, daySpan + months[index])
            }
        }
        return nil
    }

    private func daysSinceBase(_ date: LocalDate) -> Int {
        let calendar = Calendar(identifier: .gregorian)
        let base = calendar.date(from: DateComponents(timeZone: TimeZone(secondsFromGMT: 0), year: 1949, month: 1, day: 29)) ?? Date()
        let current = calendar.date(from: DateComponents(timeZone: TimeZone(secondsFromGMT: 0), year: date.year, month: date.month, day: date.day)) ?? Date()
        return Int(current.timeIntervalSince(base) / 86_400)
    }

    private func leapMonth(_ data: Int) -> Int? {
        let month = data & 0x0f
        return month == 0 ? nil : month
    }

    private func leapMonthDays(_ data: Int) -> Int {
        leapMonth(data) == nil ? 0 : ((data & 0xf0000) == 0 ? 29 : 30)
    }

    private func lunarYearDays(_ data: Int) -> Int {
        var total = 0
        var mask = 0x8000
        while mask > 0x8 {
            total += (data & mask) == 0 ? 29 : 30
            mask >>= 1
        }
        return total + leapMonthDays(data)
    }

    private func lunarYearMonths(_ data: Int) -> [Int] {
        var months: [Int] = []
        var mask = 0x8000
        while mask > 0x8 {
            months.append((data & mask) == 0 ? 29 : 30)
            mask >>= 1
        }
        if let leap = leapMonth(data) {
            months.insert(leapMonthDays(data), at: leap)
        }
        return months
    }

    // With a leap month, `months` has 13 entries and the inserted leap slot is
    // at index `leap`. Slots before it are months 1…leap, the slot itself is
    // 闰{leap}月, and slots after it map back to their ordinal month number.
    private func normalizedMonth(_ index: Int, _ leap: Int?) -> (number: Int, isLeap: Bool) {
        guard let leap else {
            return (index + 1, false)
        }
        if leap > index { return (index + 1, false) }
        if leap == index { return (index, true) }
        return (index, false)
    }

    private func yearName(_ year: Int) -> String {
        "\(stems[(year - 4) % 10])\(branches[(year - 4) % 12])"
    }

    private func monthName(_ month: Int, isLeap: Bool) -> String {
        let label = monthLabels[max(0, min(month - 1, monthLabels.count - 1))]
        return isLeap ? "闰\(label)" : label
    }

    private func dayName(_ day: Int) -> String {
        if day < 11 { return "\(dayDigits[10])\(dayDigits[day - 1])" }
        if day < 20 { return "\(dayDigits[9])\(dayDigits[day - 11])" }
        if day == 20 { return "\(dayDigits[1])\(dayDigits[9])" }
        if day < 30 { return "\(dayDigits[11])\(dayDigits[day - 21])" }
        return "\(dayDigits[2])\(dayDigits[9])"
    }

    // Valid independently of the lunar table range (e.g. 1949-01-01…28).
    func solarTerm(for date: LocalDate) -> String? {
        let first = (date.month - 1) * 2
        if date.day == solarTermDay(year: date.year, index: first) {
            return termLabels[first]
        }
        if date.day == solarTermDay(year: date.year, index: first + 1) {
            return termLabels[first + 1]
        }
        return nil
    }

    private func solarTermDay(year: Int, index: Int) -> Int {
        if year >= termTableStartYear, year <= termTableEndYear {
            let row = termTable[year - termTableStartYear]
            let offsetChar = row[row.index(row.startIndex, offsetBy: index)]
            return termBaseDays[index] + (Int(String(offsetChar)) ?? 0)
        }
        // Outside the table the legacy linear formula is used; it is only
        // accurate to about ±1 day and exists so distant calendar browsing
        // stays populated. It reads the result in UTC to stay byte-identical
        // with the TypeScript fallback in core-calendar.
        let base = Date(timeIntervalSince1970: -2_208_549_300)
        let offset = Double(year - 1900) * 31_556_925.9747 + Double(termOffsets[index]) * 60
        var calendar = Calendar(identifier: .gregorian)
        calendar.timeZone = TimeZone(secondsFromGMT: 0) ?? .current
        return calendar.component(.day, from: base.addingTimeInterval(offset))
    }
}
